insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  1,
  $wyb$An inbox triage agent that logs into your real Gmail account, pulls your unread messages, and asks Claude to decide -- in a single call -- how urgent each one is and whether it is worth drafting a reply. HIGH and MEDIUM priority emails get labeled and a ready-to-review draft saved in Gmail; LOW priority ones (newsletters, receipts, FYI-only mail) just get labeled and left alone. Nothing is ever sent automatically -- you read and send every draft yourself.$wyb$,
  $wyl$["Authenticate a Python script with Google's OAuth 2.0 flow", "Parse real Gmail API responses -- nested MIME parts, base64url bodies, missing headers", "Design one AI prompt that classifies priority AND drafts a reply, to cut API calls in half", "Use bracket markers instead of JSON so a malformed AI reply degrades instead of crashing your script", "Apply Gmail labels and save drafts programmatically", "Tell apart two different AI failure modes: a request that never completed vs. one that answered in an unusable shape", "Test parsing logic against fake data instead of a live account"]$wyl$::jsonb,
  $sess${"model": "Claude Haiku 4.5 (via your AI Builder credits)", "totalTime": "150 min", "buildCount": 5, "whatYouNeed": ["Your AI Builder key (Credits page on your dashboard)", "Python 3.10+ installed", "A Gmail account", "A free Google Cloud account (console.cloud.google.com)"], "outcomes": ["Authenticate with your own Gmail account using OAuth 2.0", "Parse real Gmail API data: nested MIME parts, base64url-encoded bodies, missing headers", "Design one AI prompt that classifies priority AND drafts a reply, instead of two separate calls", "Apply Gmail labels and save draft replies programmatically -- nothing is ever auto-sent", "Handle a malformed or missing AI reply without your script crashing", "Run a real end-to-end triage pass against your own inbox"], "builds": [{"number": 1, "title": "Parse real Gmail data -- before you touch OAuth", "time": "25 min", "description": "Gmail's API returns deeply nested JSON, and the fastest way to learn its shape is to test against a copy of it you already have -- not to debug it live against your real inbox while also fighting a browser consent screen. This build writes and tests every parsing helper gmail_client.py needs, using fake Gmail responses shaped exactly like the real thing.", "steps": [{"instruction": "Create `gmail_client.py` with this code:", "prompt": "\"\"\"\nStep 1 of the Gmail AI Triage Agent.\n\nThis file talks to Gmail: it logs you in with OAuth, fetches your unread\nmessages, and applies labels back onto them. Everything in here that\n*parses* a message (get_header, get_plain_text, parse_message) is pure\nPython with no network call in it - which is why the self-test at the\nbottom can check all of it thoroughly without a Gmail account, a browser,\nor credentials.json. The functions that DO need a real login\n(get_gmail_service, list_unread_messages, apply_label, save_draft) can\nonly be checked by actually running Build 2 against your own inbox.\n\"\"\"\n\nimport base64\nimport email.mime.text\nimport os\n\nfrom google.auth.transport.requests import Request\nfrom google.oauth2.credentials import Credentials\nfrom google_auth_oauthlib.flow import InstalledAppFlow\nfrom googleapiclient.discovery import build\n\n# Two scopes, not one. gmail.modify lets us read mail and add/remove\n# labels; gmail.compose lets us save draft replies. Neither includes\n# gmail.send - this project only ever creates a DRAFT, it never sends\n# email by itself. That's a deliberate safety boundary: a bad\n# classification can leave the wrong label on a message, but it can\n# never mail someone a reply you never saw.\nSCOPES = [\n    \"https://www.googleapis.com/auth/gmail.modify\",\n    \"https://www.googleapis.com/auth/gmail.compose\",\n]\n\nTOKEN_FILE = \"token.json\"\nCREDENTIALS_FILE = \"credentials.json\"\n\n# How many unread emails to pull per run. This is a MONEY decision as\n# much as a UX one: main.py calls the AI once per email in this list, so\n# max_results scales your credit spend directly. 10 clears a normal\n# inbox backlog without one run eating a big slice of your allotment -\n# raising this to \"all unread\" is exactly the kind of change the\n# ai-builder-credits cost model warns against.\nMAX_RESULTS = 10\n\n\ndef get_gmail_service():\n    \"\"\"\n    Logs you in to your own Gmail account and returns a ready-to-use API\n    client (Google calls this a \"service\" object).\n\n    The first time you run this, it opens a browser tab asking you to\n    approve access - that's the OAuth consent screen from Build 2's\n    setup. After you approve it, your login is cached in token.json so\n    you won't be asked again until the token expires or you delete that\n    file.\n    \"\"\"\n    creds = None\n    if os.path.exists(TOKEN_FILE):\n        creds = Credentials.from_authorized_user_file(TOKEN_FILE, SCOPES)\n\n    if not creds or not creds.valid:\n        if creds and creds.expired and creds.refresh_token:\n            creds.refresh(Request())\n        else:\n            if not os.path.exists(CREDENTIALS_FILE):\n                raise FileNotFoundError(\n                    \"credentials.json not found.\\n\"\n                    \"Download it from Google Cloud Console > APIs & Services > \"\n                    \"Credentials (see the README's Build 2 setup), and save it \"\n                    \"in this same folder, next to gmail_client.py.\"\n                )\n            flow = InstalledAppFlow.from_client_secrets_file(CREDENTIALS_FILE, SCOPES)\n            creds = flow.run_local_server(port=0)\n\n        with open(TOKEN_FILE, \"w\") as token_file:\n            token_file.write(creds.to_json())\n\n    return build(\"gmail\", \"v1\", credentials=creds)\n\n\ndef get_header(headers, name):\n    \"\"\"\n    Gmail stores each header (Subject, From, Date, ...) as its own small\n    dict inside a list, rather than one dict you could index straight\n    into - this walks that list and pulls out the one you asked for.\n\n        get_header(payload[\"headers\"], \"Subject\")\n\n    Returns \"\" if the header isn't present, instead of raising, because a\n    message with no Subject header is a normal thing some automated mail\n    sends - it shouldn't crash triage over one missing header.\n    \"\"\"\n    for header in headers:\n        if header.get(\"name\", \"\").lower() == name.lower():\n            return header.get(\"value\", \"\")\n    return \"\"\n\n\ndef get_plain_text(payload):\n    \"\"\"\n    Digs the readable text out of a Gmail message payload.\n\n    A message with both an HTML and a plain-text version comes back as a\n    \"multipart\" payload, where the text you actually want is buried\n    inside payload[\"parts\"] - and sometimes nested two levels deep\n    (multipart/mixed containing multipart/alternative, for example, on a\n    message with an attachment). This walks that structure recursively\n    and returns the first text/plain part it finds.\n    \"\"\"\n    if payload.get(\"mimeType\") == \"text/plain\":\n        data = payload.get(\"body\", {}).get(\"data\")\n        return _decode_base64url(data) if data else \"\"\n\n    for part in payload.get(\"parts\", []):\n        text = get_plain_text(part)\n        if text:\n            return text\n\n    return \"\"\n\n\ndef _decode_base64url(data):\n    # Gmail encodes body data as \"base64url\" (using '-' and '_' in place\n    # of the usual '+' and '/') and sometimes hands it back with the\n    # trailing '=' padding stripped off. Padding it back out before\n    # decoding avoids a binascii.Error: Incorrect padding crash that\n    # otherwise looks completely unrelated to what's actually wrong.\n    padded = data + \"=\" * (-len(data) % 4)\n    return base64.urlsafe_b64decode(padded).decode(\"utf-8\", errors=\"replace\")\n\n\ndef parse_message(message):\n    \"\"\"\n    Turns one raw Gmail API message dict into the simple shape the rest\n    of this project uses everywhere:\n\n        {\"id\": \"...\", \"sender\": \"...\", \"subject\": \"...\", \"body\": \"...\"}\n\n    Keeping this conversion in one place means classifier.py and main.py\n    never have to know what Gmail's actual JSON looks like.\n    \"\"\"\n    headers = message.get(\"payload\", {}).get(\"headers\", [])\n    body = get_plain_text(message.get(\"payload\", {}))\n\n    return {\n        \"id\": message.get(\"id\", \"\"),\n        \"sender\": get_header(headers, \"From\"),\n        \"subject\": get_header(headers, \"Subject\") or \"(no subject)\",\n        \"body\": body.strip(),\n    }\n\n\ndef list_unread_messages(service, max_results=MAX_RESULTS):\n    \"\"\"\n    Fetches your most recent unread inbox messages, already converted to\n    the simple dict shape from parse_message().\n\n    This makes two kinds of Gmail API call per message: one to list\n    message IDs, then one per ID to fetch the full message. That's how\n    Gmail's API works - the list endpoint deliberately returns only IDs,\n    to keep a mailbox-wide search cheap even when you don't need every\n    message's full contents.\n    \"\"\"\n    response = (\n        service.users()\n        .messages()\n        .list(userId=\"me\", labelIds=[\"UNREAD\", \"INBOX\"], maxResults=max_results)\n        .execute()\n    )\n\n    messages = []\n    for item in response.get(\"messages\", []):\n        full = (\n            service.users()\n            .messages()\n            .get(userId=\"me\", id=item[\"id\"], format=\"full\")\n            .execute()\n        )\n        messages.append(parse_message(full))\n\n    return messages\n\n\ndef get_or_create_label(service, name):\n    \"\"\"\n    Finds the Gmail label ID for `name`, creating the label if it doesn't\n    exist yet. Gmail's API identifies labels by an opaque ID everywhere\n    except this one lookup-by-name call - so every other function in\n    this project can just say \"URGENT\" instead of juggling IDs.\n    \"\"\"\n    existing = service.users().labels().list(userId=\"me\").execute()\n    for label in existing.get(\"labels\", []):\n        if label[\"name\"] == name:\n            return label[\"id\"]\n\n    created = (\n        service.users()\n        .labels()\n        .create(\n            userId=\"me\",\n            body={\n                \"name\": name,\n                \"labelListVisibility\": \"labelShow\",\n                \"messageListVisibility\": \"show\",\n            },\n        )\n        .execute()\n    )\n    return created[\"id\"]\n\n\ndef apply_label(service, message_id, label_name):\n    \"\"\"\n    Applies a label to a message and removes UNREAD, so a triaged message\n    stops showing up as unread once it's been through this pipeline.\n    \"\"\"\n    label_id = get_or_create_label(service, label_name)\n    service.users().messages().modify(\n        userId=\"me\",\n        id=message_id,\n        body={\"addLabelIds\": [label_id], \"removeLabelIds\": [\"UNREAD\"]},\n    ).execute()\n\n\ndef save_draft(service, message_id, sender, reply_text):\n    \"\"\"\n    Saves an AI-written reply as a Gmail DRAFT addressed to the sender -\n    it never sends anything. You read and send every draft yourself.\n    `message_id` isn't used by the Gmail API call itself, but it's kept\n    in the signature so main.py's call reads clearly next to apply_label.\n    \"\"\"\n    mime_message = email.mime.text.MIMEText(reply_text)\n    mime_message[\"to\"] = sender\n    raw = base64.urlsafe_b64encode(mime_message.as_bytes()).decode()\n\n    service.users().drafts().create(userId=\"me\", body={\"message\": {\"raw\": raw}}).execute()\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing works - no Gmail\n    # account, browser, or credentials.json needed:  python gmail_client.py\n    fake_message = {\n        \"id\": \"18abc123\",\n        \"payload\": {\n            \"mimeType\": \"multipart/alternative\",\n            \"headers\": [\n                {\"name\": \"From\", \"value\": \"boss@example.com\"},\n                {\"name\": \"Subject\", \"value\": \"Server is down\"},\n            ],\n            \"parts\": [\n                {\n                    \"mimeType\": \"text/plain\",\n                    \"body\": {\n                        \"data\": base64.urlsafe_b64encode(\n                            b\"Please call me ASAP, prod is down.\"\n                        ).decode()\n                    },\n                },\n                {\n                    \"mimeType\": \"text/html\",\n                    \"body\": {\n                        \"data\": base64.urlsafe_b64encode(\n                            b\"<p>Please call me ASAP, prod is down.</p>\"\n                        ).decode()\n                    },\n                },\n            ],\n        },\n    }\n\n    parsed = parse_message(fake_message)\n    print(\"Parsed a fake multipart message:\")\n    print(parsed)\n    assert parsed[\"sender\"] == \"boss@example.com\"\n    assert parsed[\"subject\"] == \"Server is down\"\n    assert \"ASAP\" in parsed[\"body\"]\n\n    # A message missing its Subject header entirely - real automated mail\n    # does this. Must not crash.\n    no_subject = {\n        \"payload\": {\n            \"mimeType\": \"text/plain\",\n            \"headers\": [{\"name\": \"From\", \"value\": \"a@b.com\"}],\n            \"body\": {\"data\": base64.urlsafe_b64encode(b\"hi\").decode()},\n        }\n    }\n    assert parse_message(no_subject)[\"subject\"] == \"(no subject)\"\n    print(\"\\nMessage with no Subject header correctly defaulted to '(no subject)'.\")\n\n    # Gmail sometimes strips the '=' padding base64 normally requires.\n    # Confirm _decode_base64url() copes with that, not just with the\n    # neatly-padded strings base64.urlsafe_b64encode() always produces.\n    unpadded = base64.urlsafe_b64encode(b\"stripped padding test\").decode().rstrip(\"=\")\n    assert _decode_base64url(unpadded) == \"stripped padding test\"\n    print(\"Un-padded base64 (Gmail's real quirk) decoded correctly.\")\n\n    print(\"\\nAll parsing checks passed. Real Gmail API responses have this exact shape.\")\n", "verify": "Run `python gmail_client.py`. You should see: `Parsed a fake multipart message:` followed by a dict with sender, subject, and body filled in, then three lines each ending `correctly ...` (defaulted / decoded), and finally `All parsing checks passed. Real Gmail API responses have this exact shape.`"}], "goFurther": "Add a third fake message to the self-test: one where `payload[\"parts\"]` is nested three levels deep (a multipart/mixed containing a multipart/alternative containing the text/plain part -- the shape a real forwarded email with an attachment actually has). Confirm `get_plain_text` still finds the text without you changing a single line of it -- that's what the recursive call buys you."}, {"number": 2, "title": "Connect to your real Gmail account", "time": "35 min", "description": "OAuth is the one part of this project you can't fake -- it needs your actual Google account and a real consent screen. This build is mostly clicking through Google Cloud Console, then running the login flow gmail_client.py already has from Build 1.", "steps": [{"instruction": "In your browser, go to console.cloud.google.com and create a new project (any name -- e.g. \"Gmail Triage Agent\"). Go to APIs & Services > Library, search for \"Gmail API\", and click Enable."}, {"instruction": "Still in Google Cloud Console, go to APIs & Services > OAuth consent screen, choose \"External\", fill in an app name and your email, and add your own Gmail address as a Test User (apps in \"Testing\" mode only allow logins from accounts on that list). Then go to Credentials > Create Credentials > OAuth client ID, choose \"Desktop app\", and download the JSON file. Rename it to exactly `credentials.json` and put it in the same folder as `gmail_client.py`."}, {"instruction": "Test the real login. In your terminal, run:", "prompt": "python -c \"from gmail_client import get_gmail_service; get_gmail_service(); print('Logged in. token.json saved.')\"", "verify": "A browser tab opens asking you to log in to Google and approve access to your Gmail. After you approve it, your terminal prints `Logged in. token.json saved.` and a new `token.json` file appears in your project folder."}], "goFurther": "Go to myaccount.google.com/permissions, find this app, and click Remove Access. Run the login test again -- Google makes you re-approve, and a fresh token.json is written. This is why `SCOPES` only asks for `gmail.modify` and `gmail.compose`, never `gmail.send`: even a leaked or revoked token can only ever create drafts, never send mail on its own."}, {"number": 3, "title": "Build the triage classifier", "time": "30 min", "description": "This is the one point in the whole project where the AI gets called. It has to do two jobs in a single request -- decide urgency and draft a reply -- because calling the AI twice per email would double what this project costs to run every time you use it.", "steps": [{"instruction": "Create `classifier.py` with this code:", "prompt": "\"\"\"\nStep 2 of the Gmail AI Triage Agent.\n\nThis file asks Claude to do two things in a single call: decide how\nurgent an email is, and draft a short reply if one is worth writing.\nAsking both questions in one request (instead of a classify call followed\nby a separate draft-a-reply call) is a deliberate cost choice, not just a\nsimplification - see build_prompt() below.\n\"\"\"\n\nfrom sdt_ai import ask_ai\n\nPRIORITIES = [\"HIGH\", \"MEDIUM\", \"LOW\"]\n\n# Stop the email body here before sending it to the AI. Same money\n# reasoning as the social post generator's MAX_CHARACTERS, but it matters\n# even more here: main.py calls the AI once PER EMAIL in a loop of up to\n# 10, so one unusually long email (a forwarded thread with three quoted\n# replies underneath it, say) costs 10x what a normal one does if it\n# isn't capped - and the quoted history under a forward almost never\n# changes how the NEW message on top should be triaged.\nMAX_BODY_CHARACTERS = 2000\n\n\ndef build_prompt(email):\n    \"\"\"\n    Writes the instructions we send to the AI for one email.\n\n    We ask for PRIORITY, REASON and REPLY in the SAME request rather than\n    classifying first and then making a second call to draft a reply.\n    That halves the number of AI calls this project makes - for a\n    12-email inbox that's the difference between 12 requests and 24. The\n    tradeoff is a slightly busier prompt and parser (see parse_reply\n    below), which is worth it precisely because this runs in a loop.\n    \"\"\"\n    body = email[\"body\"][:MAX_BODY_CHARACTERS]\n\n    return f\"\"\"You are triaging one email for a busy inbox owner.\n\nFrom: {email['sender']}\nSubject: {email['subject']}\nBody:\n{body}\n\nDecide how urgent this email is, and draft a short reply IF AND ONLY IF\nit is HIGH or MEDIUM priority. LOW priority emails (newsletters, receipts,\nautomated notifications, FYI-only messages) do not get a drafted reply.\n\nFormat your answer EXACTLY like this:\n\n[PRIORITY]\none word: HIGH, MEDIUM, or LOW\n\n[REASON]\none short sentence explaining why\n\n[REPLY]\na short, professional reply under 80 words - or the single word NONE if\npriority is LOW\n\n[END]\n\nDo not add any explanation, introduction, or closing remark outside these\nsections.\"\"\"\n\n\ndef parse_reply(reply):\n    \"\"\"\n    Turns the AI's one answer into a dict:\n\n        {\"priority\": \"HIGH\", \"reason\": \"...\", \"reply\": \"...\" or None}\n\n    Same [MARKER] approach as the social post generator, and for the same\n    reason: raw JSON breaks the moment the AI adds a stray \"Sure, here's\n    the triage:\" before the data, or wraps its answer in a code fence -\n    and for an inbox tool that runs unattended, a crash is worse than a\n    slightly imperfect parse.\n\n    Returns None (never raises) if the AI's answer had no recognizable\n    [PRIORITY] section at all. main.py checks for that and skips the\n    email rather than guessing a label for it.\n    \"\"\"\n    sections = {}\n    current = None\n    lines = []\n\n    for line in reply.splitlines():\n        stripped = line.strip()\n        marker = stripped.strip(\"[]\").upper()\n        is_marker = stripped.startswith(\"[\") and stripped.endswith(\"]\")\n\n        if is_marker and marker == \"END\":\n            break\n\n        if is_marker and marker in (\"PRIORITY\", \"REASON\", \"REPLY\"):\n            if current:\n                sections[current] = \"\\n\".join(lines).strip()\n            current = marker\n            lines = []\n        elif current:\n            # The AI occasionally wraps its whole answer in ``` code\n            # fences even when explicitly told not to - drop those lines\n            # rather than let them end up inside a drafted reply.\n            if stripped.startswith(\"```\"):\n                continue\n            lines.append(line)\n\n    if current:\n        sections[current] = \"\\n\".join(lines).strip()\n\n    if \"PRIORITY\" not in sections:\n        return None\n\n    priority = sections[\"PRIORITY\"].upper()\n    if priority not in PRIORITIES:\n        # The AI sometimes answers \"HIGH.\" with trailing punctuation, or\n        # \"HIGH - because it's time sensitive\". Take the first\n        # recognizable priority word inside the section rather than\n        # throwing the whole classification away over one stray period.\n        priority = next((p for p in PRIORITIES if p in priority), None)\n        if not priority:\n            return None\n\n    reply_text = sections.get(\"REPLY\", \"\").strip()\n    if not reply_text or reply_text.upper() == \"NONE\":\n        reply_text = None\n\n    return {\n        \"priority\": priority,\n        \"reason\": sections.get(\"REASON\", \"\").strip(),\n        \"reply\": reply_text,\n    }\n\n\ndef classify_email(email):\n    \"\"\"\n    The main function. Give it one parsed email (the dict shape that\n    gmail_client.parse_message returns), get back its priority, the\n    reason, and an optional drafted reply.\n\n        result = classify_email(email)\n        print(result[\"priority\"])\n\n    Returns None if the AI's reply couldn't be parsed at all - a real\n    possibility with any LLM, not a bug in this code - so main.py must\n    handle that case rather than assume classification always succeeds.\n    \"\"\"\n    prompt = build_prompt(email)\n\n    # max_tokens=300 is generous for one priority word, one sentence, and\n    # an 80-word reply. Capping it keeps one unusually verbose response\n    # from burning through credits it has no real use for.\n    reply = ask_ai(prompt, max_tokens=300, project=\"gmail-ai-triage-agent\")\n\n    return parse_reply(reply)\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parser works - zero AI calls,\n    # zero credits spent:  python classifier.py\n    good_reply = \"\"\"[PRIORITY]\nHIGH\n\n[REASON]\nThe sender says production is down and needs a call back.\n\n[REPLY]\nGot it, calling you now.\n\n[END]\"\"\"\n\n    result = parse_reply(good_reply)\n    print(\"Well-formed reply parsed as:\", result)\n    assert result[\"priority\"] == \"HIGH\"\n    assert result[\"reply\"] == \"Got it, calling you now.\"\n\n    low_priority_reply = \"\"\"[PRIORITY]\nLOW\n\n[REASON]\nThis is a newsletter with no action needed.\n\n[REPLY]\nNONE\n\n[END]\"\"\"\n    low_result = parse_reply(low_priority_reply)\n    assert low_result[\"priority\"] == \"LOW\"\n    assert low_result[\"reply\"] is None\n    print(\"LOW priority with REPLY: NONE correctly produced reply=None.\")\n\n    # A malformed reply: no markers at all, just prose. This must not\n    # crash - it must come back as None so main.py can skip this email\n    # instead of mislabeling it.\n    malformed_reply = \"Sure! I'd say this one is pretty urgent, you should reply soon.\"\n    assert parse_reply(malformed_reply) is None\n    print(\"Malformed reply (no markers at all) correctly returned None instead of crashing.\")\n\n    # A messy but recoverable reply: chatter before the markers, and\n    # lowercase/punctuation on the priority word.\n    messy_reply = \"\"\"Sure, here's my triage:\n\n[PRIORITY]\nmedium.\n\n[REASON]\nNeeds a reply this week but nothing urgent.\n\n[REPLY]\nThanks for the update, I'll follow up by Friday.\n\n[END]\n\nLet me know if you'd like a different tone!\"\"\"\n    messy_result = parse_reply(messy_reply)\n    assert messy_result is not None\n    assert messy_result[\"priority\"] == \"MEDIUM\"\n    print(\"Messy reply (extra prose, lowercase, trailing period) still parsed correctly.\")\n\n    print(\"\\nAll parser checks passed.\")\n", "verify": "Run `python classifier.py`. You should see the well-formed reply dict printed, then four lines each ending `... correctly` / `... correctly returned None instead of crashing` / `... still parsed correctly`, and finally `All parser checks passed.`"}], "goFurther": "🛠️ Break it on purpose: open a Python shell in this folder and run `from classifier import parse_reply; print(parse_reply(''))` -- an empty string, simulating the AI returning nothing at all (this happens on a timeout). It returns `None` instead of raising an exception, because `if \"PRIORITY\" not in sections: return None` catches it before anything tries to read a section that was never filled in. Now try `parse_reply(\"[PRIORITY]\\nHIGH\")` -- no REASON, no REPLY, no [END] -- and confirm it STILL returns a valid dict with `reason=''` and `reply=None`, because every `.get(...)` call in this function has a default. That's the difference between a project that survives a bad AI response and one that crashes at 3am while you're asleep."}, {"number": 4, "title": "Wire it together and run a real triage pass", "time": "35 min", "description": "Fetching, classifying, labeling, and drafting are each already written and tested on their own. This build is only the wiring, plus the two different ways an AI call can go wrong that main.py has to tell apart so one bad email doesn't take down the whole run.", "steps": [{"instruction": "Create `main.py` with this code:", "prompt": "\"\"\"\nStep 3 of the Gmail AI Triage Agent - ties fetching, classifying, and\nlabeling into one script you actually run against your real inbox.\n\nRun it with:      python main.py\nSelf-test with:   python main.py --selftest   (fakes Gmail and the AI,\n                   so it costs no credits and never touches a real inbox -\n                   it only checks that the wiring below handles a\n                   successful email and an unparseable one correctly.)\n\"\"\"\n\nimport sys\n\nfrom classifier import classify_email\nfrom gmail_client import apply_label, get_gmail_service, list_unread_messages, save_draft\nfrom sdt_ai import AIError\n\n# Every priority gets a Gmail label, so triage results are visible in\n# your inbox sidebar - not just in this script's console output.\nLABEL_FOR_PRIORITY = {\n    \"HIGH\": \"URGENT\",\n    \"MEDIUM\": \"IMPORTANT\",\n    \"LOW\": \"LOW\",\n}\n\n\ndef triage_inbox():\n    \"\"\"\n    Fetches your unread emails, classifies each one, applies a label, and\n    drafts a reply for anything HIGH or MEDIUM priority.\n\n    Returns the list of emails that were successfully triaged, so the\n    caller (the __main__ block below, or your own script later) can see\n    what happened without re-parsing console output.\n    \"\"\"\n    service = get_gmail_service()\n    emails = list_unread_messages(service)\n\n    if not emails:\n        print(\"No unread emails to triage.\")\n        return []\n\n    results = []\n    for email in emails:\n        try:\n            classification = classify_email(email)\n        except AIError as problem:\n            # One bad AI call (network hiccup, low credit balance, the\n            # gateway being paused) shouldn't take down the whole run -\n            # print why and move to the next email. sdt_ai only raises\n            # AIError for requests that never completed, so no credits\n            # were spent on this one.\n            print(f\"  Skipped '{email['subject']}': {problem}\")\n            continue\n\n        if classification is None:\n            # Different from the AIError case above: the AI DID answer,\n            # it just wasn't in a shape parse_reply() could read. This is\n            # rarer, but real with any LLM - printed distinctly so you\n            # can tell \"the AI never answered\" apart from \"the AI\n            # answered oddly\" when you're debugging a run later.\n            print(f\"  Could not parse the AI's reply for '{email['subject']}' - skipping, no label applied.\")\n            continue\n\n        label = LABEL_FOR_PRIORITY[classification[\"priority\"]]\n        apply_label(service, email[\"id\"], label)\n\n        if classification[\"reply\"]:\n            save_draft(service, email[\"id\"], email[\"sender\"], classification[\"reply\"])\n\n        print(f\"  [{classification['priority']}] {email['subject']} - {classification['reason']}\")\n        results.append({**email, **classification, \"label\": label})\n\n    return results\n\n\nif __name__ == \"__main__\":\n    if \"--selftest\" in sys.argv:\n        # Fakes stand in for Gmail and the AI, so this checks the WIRING\n        # (skip on AIError, skip on an unparseable reply, label + draft\n        # otherwise) without a Gmail login, a network call, or a single\n        # credit spent. Reassigning these names at module level works\n        # because triage_inbox() above looks them up as globals each\n        # time it's called - it doesn't matter that they started out as\n        # imports from gmail_client and classifier.\n        calls = []\n\n        def fake_get_gmail_service():\n            return \"FAKE_SERVICE\"\n\n        def fake_list_unread_messages(service):\n            return [\n                {\"id\": \"1\", \"sender\": \"a@b.com\", \"subject\": \"Urgent thing\", \"body\": \"help, now\"},\n                {\"id\": \"2\", \"sender\": \"c@d.com\", \"subject\": \"Weird one\", \"body\": \"??\"},\n            ]\n\n        def fake_classify_email(email):\n            if email[\"id\"] == \"2\":\n                return None  # simulates an AI reply that didn't parse\n            return {\"priority\": \"HIGH\", \"reason\": \"test reason\", \"reply\": \"ok, on it\"}\n\n        def fake_apply_label(service, message_id, label):\n            calls.append((\"label\", message_id, label))\n\n        def fake_save_draft(service, message_id, sender, reply_text):\n            calls.append((\"draft\", message_id))\n\n        get_gmail_service = fake_get_gmail_service\n        list_unread_messages = fake_list_unread_messages\n        classify_email = fake_classify_email\n        apply_label = fake_apply_label\n        save_draft = fake_save_draft\n\n        results = triage_inbox()\n        assert len(results) == 1, \"the unparseable email should have been skipped, not counted\"\n        assert (\"label\", \"1\", \"URGENT\") in calls, \"the parseable email should have been labeled URGENT\"\n        assert (\"draft\", \"1\") in calls, \"a HIGH priority email with a reply should get a draft\"\n        assert not any(call[1] == \"2\" for call in calls), \"the skipped email must not get a label or draft\"\n        print(\"Self-test passed: unparseable reply skipped, valid one labeled URGENT and drafted.\")\n    else:\n        print(\"Checking your inbox...\\n\")\n        triage_inbox()\n        print(\"\\nDone. Check Gmail: labels should be applied, and drafts saved for anything HIGH or MEDIUM.\")\n", "verify": "Run `python main.py --selftest` (fakes Gmail and the AI, spends no credits, touches no real inbox). You should see `[HIGH] Urgent thing - test reason`, then `Could not parse the AI's reply for 'Weird one' - skipping, no label applied.`, then `Self-test passed: unparseable reply skipped, valid one labeled URGENT and drafted.`"}, {"instruction": "Now run it for real against your own inbox:", "prompt": "python main.py", "verify": "One line per real unread email prints, showing its priority and Claude's one-sentence reason. Open Gmail in your browser: you should see new URGENT / IMPORTANT / LOW labels applied, and a draft reply waiting in your Drafts folder for anything HIGH or MEDIUM."}], "goFurther": "🛠️🛠️ Send yourself two test emails -- one titled \"URGENT: server is down, need you now\" and a casual one like \"Lunch on Friday?\" -- then run `python main.py` again and confirm they land under different labels, with a genuinely different-toned drafted reply (or no draft at all) for the casual one."}, {"number": 5, "phaseLabel": "🎯 Challenge", "title": "Challenge: Add a NEWSLETTER category that gets skipped entirely", "time": "25 min", "description": "Right now every email gets a label, even a newsletter you will never reply to. The real test of whether you understand this pipeline -- not just whether it runs -- is extending the prompt AND the parser together, since they are two halves of one contract: change what you ask the AI for without also changing how your code reads the answer, and you get silently wrong behavior, not a helpful error.", "steps": [{"instruction": "In `classifier.py`, add a fourth option, `NEWSLETTER`, for anything the sender clearly never expects a reply to (marketing mail, automated digests, no-reply addresses). A NEWSLETTER email should skip labeling AND drafting entirely -- `main.py`'s loop should just print that it skipped one and move to the next email, the same way it already does for an AIError.", "prompt": "# In classifier.py:\nPRIORITIES = [\"HIGH\", \"MEDIUM\", \"LOW\", \"NEWSLETTER\"]\n\n# Add NEWSLETTER to the prompt's format instructions inside build_prompt() too --\n# an option you never mention to the AI is one it will never pick, no matter\n# how obviously an email fits it.\n\n# In main.py's triage_inbox(), right after the existing\n# `if classification is None:` check, add a new branch:\n#   if classification[\"priority\"] == \"NEWSLETTER\": ...\n# print a skip message and `continue` -- same pattern as the branches\n# already above it, not a rewrite of the loop.", "verify": "Send yourself a clearly promotional email (or forward a real marketing newsletter to yourself) and run `python main.py`. Its priority must come back as `NEWSLETTER`, not `LOW` -- and it must get NO Gmail label and NO draft reply, while any other real unread emails in your inbox are still triaged normally in that same run. If it still comes back LOW, check that you added NEWSLETTER inside `build_prompt`'s instructions, not just to the `PRIORITIES` list -- the AI can only choose an option you actually told it about."}]}], "portfolio": "You built a Gmail triage agent that logs into your real inbox, classifies unread mail by urgency using Claude, auto-labels it, and drafts context-aware replies -- through your own AI Builder credits, with no personal Anthropic subscription or API key required.", "portfolioPrompt": "I just built a Gmail AI Triage Agent that logs into my real Gmail account, classifies unread emails as HIGH/MEDIUM/LOW priority using Claude, applies matching labels automatically, and drafts short replies for anything urgent or important -- using bracket-marker prompting so a malformed AI reply never crashes the script.\n\nHelp me write:\n1. A 2-3 sentence project description for my portfolio site\n2. A short LinkedIn post announcing it\n3. Three resume-style bullet points describing what I built and the skills it shows"}$sess$::jsonb,
  null, null,
  $tsh$[{"issue": "Error 403: access_denied on the Google login screen", "fix": "Go to Google Cloud Console > APIs & Services > OAuth consent screen > Test users, and add your own Google account as a test user. Apps in \"Testing\" mode only allow logins from accounts on that list."}, {"issue": "Error: redirect_uri_mismatch when the browser tab opens", "fix": "Your OAuth client ID must be type \"Desktop app\", not \"Web application\" -- desktop apps handle the local redirect automatically. Create a new Desktop app client ID in Google Cloud Console if you picked the wrong type, and re-download credentials.json."}, {"issue": "google.auth.exceptions.RefreshError: invalid_grant when running main.py", "fix": "Your cached login has expired or been revoked (including if you clicked \"Remove Access\" at myaccount.google.com/permissions). Delete token.json and run `python -c \"from gmail_client import get_gmail_service; get_gmail_service()\"` again to redo the login."}, {"issue": "classify_email() keeps returning None for the same email every time", "fix": "The AI's reply didn't contain a recognizable [PRIORITY] marker -- usually because it added an explanation before the markers despite being told not to. Add `print(reply)` right before the `return parse_reply(reply)` line in classify_email to see the AI's actual raw answer. This is expected LLM variance, not a bug in parse_reply, which is deliberately written to return None instead of crashing when it happens -- try the same email again, or tighten the prompt's last line."}, {"issue": "main.py prints \"Skipped ...: No SDT_API_KEY found\" for every single email", "fix": "Your .env file is missing or misnamed. It must be named exactly `.env` (not `.env.example` or `.env.txt`) and sit in the same folder as main.py, with `SDT_API_KEY=your_actual_key` on one line."}, {"issue": "A drafted reply appears in Gmail with no recipient address", "fix": "Some automated senders put a display name with no real reply-to address in their From header, which get_header() returns as an empty string rather than crashing on. An empty sender means Gmail saves the draft with a blank To: field -- fill it in by hand before sending, or add a check in main.py that skips drafting when email[\"sender\"] is empty."}]$tsh$::jsonb,
  $res$[{"url": "https://developers.google.com/gmail/api", "title": "Gmail API Documentation"}, {"url": "https://developers.google.com/gmail/api/reference/rest/v1/users.messages/get", "title": "Gmail API Reference: users.messages.get (the payload/headers/body shape)"}, {"url": "https://developers.google.com/identity/protocols/oauth2/native-app", "title": "Google OAuth 2.0 for Desktop Apps"}, {"url": "https://googleapis.github.io/google-api-python-client/docs/", "title": "google-api-python-client Documentation"}]$res$::jsonb,
